import{z as d,x as B,o as l,c as p,q as E,j as i,D as o,d as t,s as n,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"多面体模型","description":"","frontmatter":{"title":"多面体模型","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/polyhedral-model.md","filePath":"cs/polyhedral-model.md","lastUpdated":1791413859000}'),A={name:"cs/polyhedral-model.md"};function u(h,a,D,m,c,f){const r=B("Mermaid");return l(),p("div",null,[a[2]||(a[2]=E('<h1 id="多面体模型" tabindex="-1">多面体模型 <a class="header-anchor" href="#多面体模型" aria-label="Permalink to &quot;多面体模型&quot;">​</a></h1><div class="epigraph"><p>静态控制部分的迭代域是多面体，依赖是仿射关系。调度用仿射变换同时表达交换、分块、并行与向量化。</p><footer>—— 据 Feautrier, Some Efficient Solutions to the Affine Scheduling Problem；Bastoul, Code Generation in the Polyhedral Model；Bondhugula 等 Pluto 整理</footer></div><p>上一课<a href="/cs/auto-vectorization">自动向量化</a>在最内层做局部判定。缺口是<strong>统一代数</strong>：SCoP（static control part）里，循环界与下标为仿射，迭代点是 \\(\\mathbb{Z}^n\\) 的多面体。Feautrier 调度、Pluto 自动分块。本课钉模型边界，不把整数规划求解器写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>手写交换/分块/向量化各一套启发式，组合爆炸。多面体：依赖多面体 + 求仿射调度函数，使依赖边时间增加。<span class="marginnote">「仿射」翻译成大白话就是「线性 + 平移」：形如 \\(2i+3j+1\\) 的表达式（常数乘变量再相加，允许加常数），而 \\(i \\cdot j\\) 或 \\(i\\) 是奇数时才执行这类判断都不算。循环界与数组下标只要全是这种形状，就能被代数符号整体操作。</span>缺口是<strong>何时程序落进模型</strong>（无 <code>while</code> 未知界、无间接下标），不是 SIMD 掩码细节。</p><p>代码生成：扫描多面体重新吐循环（CLooG 等）。</p><h3 id="多面体不是「所有循环」" tabindex="-1">多面体不是「所有循环」 <a class="header-anchor" href="#多面体不是「所有循环」" aria-label="Permalink to &quot;多面体不是「所有循环」&quot;">​</a></h3><p>链表、<code>while (p)</code>、<code>a[b[i]]</code> 通常出模型。编译器只对检测出的 SCoP 启用。不要声称整个 C 程序都在多面体里。</p><p><span class="marginnote">Feautrier 1990s。Wilde/Bastoul CLooG。Bondhugula Pluto。Polly（LLVM）、Graphite（GCC）。本课不进 polyhedral compilation 的全部 ILP 技巧。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>抽取 SCoP。建依赖。解调度（最小化通信、最大化内层并行）。生成循环。再跑向量化。失败则保持原循环。</p>',11)),(l(),i(s,null,{default:o(()=>[n(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20SCOP%5B%22%E4%BB%BF%E5%B0%84%20SCoP%22%5D%20--%3E%20DEP%5B%22%E4%BE%9D%E8%B5%96%E5%A4%9A%E9%9D%A2%E4%BD%93%22%5D%0A%20%20DEP%20--%3E%20SCH%5B%22%E4%BB%BF%E5%B0%84%E8%B0%83%E5%BA%A6%22%5D%0A%20%20SCH%20--%3E%20GEN%5B%22%E5%86%8D%E7%94%9F%E6%88%90%E5%BE%AA%E7%8E%AF%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("span",{class:"marginnote"},"直觉类比：迭代域像一块水晶——每个整数格点是一次循环迭代，循环界就是切割水晶的平面。交换循环相当于换一个方向看这块晶体，分块相当于沿格线把它切成小方块。变换只动「怎么看」，不动「晶体本身」，所以代数上统一、可组合。")],-1)),a[4]||(a[4]=e("p",null,[t("与"),e("a",{href:"/cs/abstract-interpretation"},"抽象解释"),t("：多面体是精确的迭代集表示，不是区间那么粗，但适用范围窄。")],-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,"编译时间：ILP 可能爆。实用：限维、限语句数。浮点结合与并行归约仍要语言许可。",-1)),a[7]||(a[7]=e("p",null,"调度合法性的判定机械但关键：对每条依赖边（源点、汇点），要求新调度给汇点分配的时间严格晚于源点。所有候选变换都要过这一关，一条边违例整个变换作废。",-1)),(l(),i(s,null,{default:o(()=>[n(r,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%8E%9F%E8%BF%AD%E4%BB%A3%E5%9F%9F%20%E4%BA%8C%E9%87%8D%E5%BE%AA%E7%8E%AF%20i%2Cj%22%5D%20--%3E%20B%5B%22%E4%BE%9D%E8%B5%96%E8%BE%B9%3A%20%E5%86%99%20a%5Bi%5D%5Bj%5D%20%E5%90%8E%E8%AF%BB%22%5D%0A%20%20B%20--%3E%20C%5B%22%E5%80%99%E9%80%89%E8%B0%83%E5%BA%A6%20t%20%3D%20f(i%2C%20j)%22%5D%0A%20%20C%20--%3E%20D%7B%22%E6%AF%8F%E6%9D%A1%E8%BE%B9%20f(%E6%B1%87)%20gt%20f(%E6%BA%90)%3F%22%7D%0A%20%20D%20--%20%22%E6%98%AF%22%20--%3E%20E%5B%22%E5%8F%98%E6%8D%A2%E5%90%88%E6%B3%95%EF%BC%8C%E9%87%8D%E6%8E%92%E5%BE%AA%E7%8E%AF%22%5D%0A%20%20D%20--%20%22%E5%90%A6%22%20--%3E%20F%5B%22%E4%BE%9D%E8%B5%96%E8%A2%AB%E7%BF%BB%E8%BD%AC%E8%AE%A9%E5%85%88%E5%86%99%E5%90%8E%E8%AF%BB%E9%A2%A0%E5%80%92%22%5D%0A%20%20F%20--%3E%20G%5B%22%E6%94%BE%E5%BC%83%E8%AF%A5%E5%8F%98%E6%8D%A2%E6%88%96%E6%8D%A2%E7%B3%BB%E6%95%B0%22%5D%0A"})]),fallback:o(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=E('<p><span class="marginnote">初学者容易以为循环交换总是安全的。实际上若内层读的正是外层上一轮写的元素（如按行写、按列读），交换后「后用的」反而先执行，结果全错——多面体调度就是用 \\(f(\\text{汇}) \\gt f(\\text{源})\\) 这一条不等式把这类错误在编译期拦下来。</span></p><p>不要把多面体当 GPU 自动生成的全部（还要共享内存映射等）。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 Pluto 目标函数全文。后课默认：仿射嵌套可用多面体统一变换。后课别名：模型外与模型内都要回答「是否同一位置」。</p><p>也不把线性规划当本课的优化对象（那是算法课）。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>多面体：迭代域与仿射依赖 + 调度变换。</li><li>只覆盖 SCoP；间接与 while 排除。</li><li>生成后再接向量化与分块目标。</li><li>出处：Feautrier；Bastoul；Bondhugula et al. Pluto。</li></ul>',7))])}const F=d(A,[["render",u]]);export{C as __pageData,F as default};
